private IntegrazioneRichiestaDTO mapRichiestaIntegrazioniEsecuzione(IstanzaDomandaBando istanzaDomandaBando) {
    Form form = formLocalService.fetchForm(istanzaDomandaBando.getFormId());

    IntegrazioneRichiestaDTO integrazioneRich = new IntegrazioneRichiestaDTO();
    integrazioneRich.setData(istanzaDomandaBando.getCreateDate());
    integrazioneRich.setDenominazione(form.getNome());

    DomandaBandoIntegrazione domandaIntegrazione = domandaBandoIntegrazioneLocalService.fetchDomandaBandoIntegrazione(istanzaDomandaBando.getIstanzaDomandaBandoId());
    if (Validator.isNotNull(domandaIntegrazione)) {
        integrazioneRich.setDataProtocollo(domandaIntegrazione.getDataProtocollo());
        integrazioneRich.setNumeroProtocollo(domandaIntegrazione.getNumeroProtocollo());
        integrazioneRich.setDataProtocolloUscita(domandaIntegrazione.getDataProtocolloUscita());
        integrazioneRich.setNumeroProtocolloUscita(domandaIntegrazione.getNumeroProtocolloUscita());
    }

    StatoIntegrazioneDomandaBandoEnum stato;
    if (istanzaDomandaBando.getStato() == null || istanzaDomandaBando.getStato().isBlank()) {
        stato = StatoIntegrazioneDomandaBandoEnum.NON_VALIDATA;
    }
    else {
        stato = StatoIntegrazioneDomandaBandoEnum.valueOf(istanzaDomandaBando.getStato());
    }

    integrazioneRich.setStatoEsecuzione(istanzaDomandaBando.getStato());
    integrazioneRich.setStato(stato.name());
    integrazioneRich.setIntegrativo(!form.isPrincipale());
    integrazioneRich.setIstanzaFormId(istanzaDomandaBando.getIstanzaDomandaBandoId());
    integrazioneRich.setDataCreazione(istanzaDomandaBando.getCreateDate());

    DomandaBando domandaBando = domandaBandoLocalService.fetchDomandaBando(istanzaDomandaBando.getDomandaBandoId());
    if (Validator.isNotNull(domandaBando)) {
        List<BandoForm> bandoFormList = bandoFormLocalService.getBandoFormBandoAndForm(domandaBando.getBandoId(), form.getFormId());
        if (ListUtil.isNotNull(bandoFormList) && ListUtil.isNotEmpty(bandoFormList) && bandoFormList.size() == 1) {
            BandoForm bandoForm = bandoFormList.get(0);
            TipoFormEnum tipoFormEnum = TipoFormEnum.valueOf(bandoForm.getTipoForm());
            integrazioneRich.setIntegrazione(false);
            if (Validator.isNotNull(tipoFormEnum)) {
                integrazioneRich.setIntegrazione(tipoFormEnum.isIntegrazione());
            }
        }
    }
    if (Validator.isNotNull(istanzaDomandaBando.getDataInvio())) {
        integrazioneRich.setDataInvio(istanzaDomandaBando.getDataInvio());
    }
    List<IntegrazioneAllegatoDTO> allegati = allegatoDomandaBandoLocalService.getListaAllegatiByIstanzaDomandaBandoId(istanzaDomandaBando.getIstanzaDomandaBandoId()).stream()
            .map(this::mapIntegrazioneAllegato).sorted(Comparator.comparingLong(a -> a.getDefinizioneAllegatoId())).collect(Collectors.toList());
    integrazioneRich.setAllegati(allegati);

    List<FormField> listaFieldEsecuzione = null;
    if(Validator.isNotNull(form) && !form.getJson().isEmpty()) {
        listaFieldEsecuzione = JsonPathUtil.getFormFields(form.getJson(), ScrivaniaOperatoreBandiPortletKeys.TIPO_CUSTOM_FIELD_ESECUZIONE);
    }
    if(Validator.isNotNull(listaFieldEsecuzione) && !listaFieldEsecuzione.isEmpty()) {
        boolean isIntegrazione = checkFormIntegrazione(listaFieldEsecuzione, form.getJson());
        if (isIntegrazione) {
            integrazioneRich.setEsecuzioneIntegrazione(true);
        }
    }

    String codiceFormIntegrazione = getFormIntegrazioneEsecuzione(form, istanzaDomandaBando);

    if(Validator.isNotNull(codiceFormIntegrazione) && !codiceFormIntegrazione.isEmpty()){
        integrazioneRich.setCodiceFormIntegrazionePresente(true);
    }

    return integrazioneRich;
}


private IntegrazioneAllegatoDTO mapIntegrazioneAllegato(AllegatoDomandaBando allegatoDomandaBando) {
    IntegrazioneAllegatoDTO dto = new IntegrazioneAllegatoDTO();
    dto.setDefinizioneAllegatoId(allegatoDomandaBando.getDefinizioneAllegatoId());
    dto.setNome(allegatoDomandaBando.getNome());
    dto.setTitolo(allegatoDomandaBando.getTitolo());
    dto.setIdDocumentale(allegatoDomandaBando.getIdDocumentale());
    return dto;
}

