private boolean checkFormIntegrazione(List<FormField> listaFields, String jsonForm) {
    JsonNode fieldOptions = null;
    Set<Option> jsonPathOptions = new HashSet<Option>();
    jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
    jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

    Configuration jsonPathConfiguration = Configuration.builder()
            .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
            .options(jsonPathOptions).build();
    for (FormField campo : listaFields) {
        String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
        String[] splitFields = field.split("(?<=\\])(?=\\[)");
        String jsonPathOptionsField = ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + splitFields[0] + ALPACA_FIELDS_FIELD + splitFields[1];
        fieldOptions = JsonPath.using(jsonPathConfiguration).parse(jsonForm).read(jsonPathOptionsField);

        if (Validator.isNotNull(fieldOptions) && !fieldOptions.isEmpty()) {
            JsonNode options = fieldOptions.get(0);
            if (options.has("integrazione")) {
                boolean integrazione = options.get("integrazione").asBoolean();
                if (integrazione) {
                    return true;
                }
            }
        }
    }
    return false;
}

private String getFormIntegrazioneEsecuzione(Form form, IstanzaDomandaBando istanzaDomandaBando) {
    String response = null;

    // Un'istanza non ancora compilata ha json nullo: non c'è alcun form di integrazione collegato da ricavare.
    if (istanzaDomandaBando == null || Validator.isNull(istanzaDomandaBando.getJson())) {
        return response;
    }

    List<FormField> listaField = new ArrayList<>();

    Set<Option> jsonPathOptions = new HashSet<Option>();
    jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
    jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

    Configuration jsonPathConfiguration = Configuration.builder()
            .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
            .options(jsonPathOptions).build();
    JsonObject formObject = new JsonParser().parse(istanzaDomandaBando.getJson()).getAsJsonObject();
    if (Validator.isNotNull(formObject) && formObject.has("alpaca")) {
        String jsonForm = formObject.get("alpaca").toString();
        listaField = JsonPathUtil.getFormFields(jsonForm, typesCustomFormEsecuzione);
    }
    JsonNode fieldOptions = null;

    if (Validator.isNotNull(listaField) && !listaField.isEmpty()) {
        for (FormField campo : listaField) {
            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
            String[] splitFields = field.split("(?<=\\])(?=\\[)");
            String jsonPathOptionsField = ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + splitFields[0] + ALPACA_FIELDS_FIELD + splitFields[1];
            fieldOptions = JsonPath.using(jsonPathConfiguration).parse(form.getJson()).read(jsonPathOptionsField);
            if (Validator.isNotNull(fieldOptions) && !fieldOptions.isEmpty()) {
                JsonNode options = fieldOptions.get(0);
                if (options.has("formDaMostrare")) {
                    response = options.get("formDaMostrare").asText();
                }
            }
        }
    }
    return response;
}


public byte[] getZipAllegati(long domandaBandoId, long istanzaDomandaBandoId, long groupId, boolean interno) throws Exception {
    List<AllegatoDomandaBando> allegati = allegatoDomandaBandoLocalService.getAllegatiByIstanzaDomandaBandoIdAndInterno(istanzaDomandaBandoId, interno);
    return creaZipAllegati(allegati, domandaBandoId, groupId);
}

public byte[] getZipAllegatiIntegrativi(long domandaBandoId, long istanzaDomandaBandoId, long groupId) throws Exception {
    List<AllegatoDomandaBando> allegati = allegatoDomandaBandoLocalService.getAllegatiIntegrativi(istanzaDomandaBandoId, -1, -1);
    return creaZipAllegati(allegati, domandaBandoId, groupId);
}

private byte[] creaZipAllegati(List<AllegatoDomandaBando> allegati, long domandaBandoId, long groupId) throws Exception {
    String identificativoRichiedente = null;
    try {
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);
        if (Validator.isNotNull(domandaBando)) {
            if (Validator.isNotNull(domandaBando.getPartitaIva())) {
                identificativoRichiedente = domandaBando.getPartitaIva();
            } else if (Validator.isNotNull(domandaBando.getCodiceFiscale())) {
                identificativoRichiedente = domandaBando.getCodiceFiscale();
