private void handleTabServiziEsecuzione(RenderRequest renderRequest, DomandaBando domandaBando) {
    int cur = ParamUtil.getInteger(renderRequest, "curServizioEsecuzione", 1);
    int delta = ParamUtil.getInteger(renderRequest, "deltaServizioEsecuzione", 10);

    int servizioEsecuzioneCount =
            scrivaniaOperatoreBandiFrontendService.countRichiesteServizioEsecuzione(domandaBando.getDomandaBandoId(), domandaBando.getBandoId());
    int[] limits = PaginationUtil.calculateStartAndEnd(cur, delta, servizioEsecuzioneCount);
    int start = limits[0];
    int end = limits[1];
    cur = limits[2];

    List<IntegrazioneRichiestaDTO> servizioEsecuzioneList = scrivaniaOperatoreBandiFrontendService.getRichiesteServiziEsecuzione(
            domandaBando.getDomandaBandoId(),
            domandaBando.getBandoId(),
            start,
            end);

    renderRequest.setAttribute("servizioEsecuzioneList", servizioEsecuzioneList);
    renderRequest.setAttribute("servizioEsecuzioneCount", servizioEsecuzioneCount);
    renderRequest.setAttribute("curServizioEsecuzione", cur);
    renderRequest.setAttribute("deltaServizioEsecuzione", delta);
}

