package it.servizidigitali.gestionebandi.operatore.frontend.portlet.action;

import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.portlet.bridges.mvc.BaseMVCActionCommand;
import com.liferay.portal.kernel.portlet.bridges.mvc.MVCActionCommand;
import com.liferay.portal.kernel.service.ServiceContext;
import com.liferay.portal.kernel.service.ServiceContextFactory;
import com.liferay.portal.kernel.util.ParamUtil;
import it.servizidigitali.gestionebandi.common.enumeration.StatoIntegrazioneDomandaBandoEnum;
import it.servizidigitali.gestionebandi.model.IstanzaDomandaBando;
import it.servizidigitali.gestionebandi.operatore.frontend.constants.AzioniOperatoreCodes;
import it.servizidigitali.gestionebandi.operatore.frontend.constants.ScrivaniaOperatoreBandiPortletKeys;
import it.servizidigitali.gestionebandi.operatore.frontend.enums.DomandaBandoTabEnum;
import it.servizidigitali.gestionebandi.service.AzioneOperatoreLocalService;
import it.servizidigitali.gestionebandi.service.IstanzaDomandaBandoLocalService;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import javax.portlet.ActionRequest;
import javax.portlet.ActionResponse;
import javax.portlet.MutableRenderParameters;
import java.util.Date;

@Component(immediate = true, service = MVCActionCommand.class, property = {
        "javax.portlet.name=" + ScrivaniaOperatoreBandiPortletKeys.SCRIVANIA_OPERATORE_BANDI,
        "mvc.command.name=" + ScrivaniaOperatoreBandiPortletKeys.RICEVUTA_ESECUZIONE_INTEGRAZIONE
})
public class RicevutaEsecuzioneIntegrazioneActionCommand extends BaseMVCActionCommand  {

    public static final Log log = LogFactoryUtil.getLog(RicevutaEsecuzioneIntegrazioneActionCommand.class);

    @Reference
    private IstanzaDomandaBandoLocalService istanzaDomandaBandoLocalService;

    @Reference
    private AzioneOperatoreLocalService azioneOperatoreLocalService;

    @Override
    protected void doProcessAction(ActionRequest actionRequest, ActionResponse actionResponse) throws Exception {
        long istanzaDomandaBandoId = ParamUtil.getLong(actionRequest, "istanzaDomandaBandoIdRicevuta");
        String queryTab = ParamUtil.getString(actionRequest, "queryTab");
        IstanzaDomandaBando istanzaDomandaBando = istanzaDomandaBandoLocalService.fetchIstanzaDomandaBando(istanzaDomandaBandoId);

        istanzaDomandaBando.setStato(StatoIntegrazioneDomandaBandoEnum.RICEVUTA.name());
        istanzaDomandaBandoLocalService.updateIstanzaDomandaBando(istanzaDomandaBando);

        ServiceContext serviceContext = ServiceContextFactory.getInstance(actionRequest);
        azioneOperatoreLocalService.addAzioneOperatore(serviceContext, istanzaDomandaBando.getDomandaBandoId(), serviceContext.getUserId(), new Date(), AzioniOperatoreCodes.PRESA_VISIONE_SERVIZIO_ESECUZIONE.name());

        MutableRenderParameters renderParameters = actionResponse.getRenderParameters();
        renderParameters.setValue("mvcRenderCommandName", ScrivaniaOperatoreBandiPortletKeys.DETTAGLIO_DOMANDA_BANDO_RENDER);
        renderParameters.setValue("domandaBandoId", String.valueOf(istanzaDomandaBando.getDomandaBandoId()));
        renderParameters.setValue("queryTab", queryTab);
        renderParameters.setValue("queryTabParent", DomandaBandoTabEnum.IN_LAVORAZIONE.getKey());
    }
}
